// TestRoleVariable tests variable parsing
func TestRoleVariable(t *testing.T) {
	var tests = []struct {
		title string
		in    string
		err   error
		out   Expression
	}{
		{
			title: "no curly bracket prefix",
			in:    "external.foo}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "invalid syntax",
			in:    `{{external.foo("bar")`,
			err:   trace.BadParameter(""),
		},
		{
			title: "invalid variable syntax",
			in:    "{{internal.}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "invalid dot syntax",
			in:    "{{external..foo}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "empty variable",
			in:    "{{}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "no curly bracket suffix",
			in:    "{{internal.foo",
			err:   trace.BadParameter(""),
		},
		{
			title: "too many levels of nesting in the variable",
			in:    "{{internal.foo.bar}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "valid with brackets",
			in:    `{{internal["foo"]}}`,
			out:   Expression{namespace: "internal", variable: "foo"},
		},
		{
			title: "string literal",
			in:    `foo`,
			out:   Expression{namespace: LiteralNamespace, variable: "foo"},
		},
		{
			title: "external with no brackets",
			in:    "{{external.foo}}",
			out:   Expression{namespace: "external", variable: "foo"},
		},
		{
			title: "internal with no brackets",
			in:    "{{internal.bar}}",
			out:   Expression{namespace: "internal", variable: "bar"},
		},
		{
			title: "internal with spaces removed",
			in:    "  {{  internal.bar  }}  ",
			out:   Expression{namespace: "internal", variable: "bar"},
		},
		{
			title: "variable with prefix and suffix",
			in:    "  hello,  {{  internal.bar  }}  there! ",
			out:   Expression{prefix: "hello,  ", namespace: "internal", variable: "bar", suffix: "  there!"},
		},
		{
			title: "variable with local function",
			in:    "{{email.local(internal.bar)}}",
			out:   Expression{namespace: "internal", variable: "bar", transform: emailLocalTransformer{}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.title, func(t *testing.T) {
			variable, err := Variable(tt.in)
			if tt.err != nil {
				assert.IsType(t, tt.err, err)
				return
			}
			assert.NoError(t, err)
			assert.Empty(t, cmp.Diff(tt.out, *variable, cmp.AllowUnexported(Expression{})))
		})
	}
}

// TestMatch checks the matcher syntax and the boundaries of each match.
func TestMatch(t *testing.T) {
	tests := []struct {
		name    string
		pattern string
		matches []string
		misses  []string
	}{
		{
			name:    "literal",
			pattern: "foo.bar",
			matches: []string{"foo.bar"},
			misses:  []string{"fooXbar", "xfoo.bar", "foo.barx"},
		},
		{
			name:    "wildcard",
			pattern: "*",
			matches: []string{"", "foo", "foo/bar"},
		},
		{
			name:    "wildcard with fixed sides",
			pattern: "foo*bar",
			matches: []string{"foobar", "foo-middle-bar"},
			misses:  []string{"xfoobar", "foobarx", "foobaz"},
		},
		{
			name:    "raw regular expression",
			pattern: "^foo[0-9]+$",
			matches: []string{"foo1", "foo123"},
			misses:  []string{"foo", "xfoo1", "foo1x"},
		},
		{
			name:    "regexp match function",
			pattern: `{{regexp.match("^foo[0-9]+$")}}`,
			matches: []string{"foo1", "foo123"},
			misses:  []string{"foo", "xfoo1", "foo1x"},
		},
		{
			name:    "regexp function uses regexp search semantics",
			pattern: `{{regexp.match("foo")}}`,
			matches: []string{"foo", "prefix-foo-suffix"},
			misses:  []string{"bar"},
		},
		{
			name:    "regexp quantifier braces inside template",
			pattern: `{{regexp.match("^a{2}$")}}`,
			matches: []string{"aa"},
			misses:  []string{"a", "aaa"},
		},
		{
			name:    "closing brackets inside quoted regexp",
			pattern: `{{regexp.match("a}}b")}}`,
			matches: []string{"a}}b"},
			misses:  []string{"ab"},
		},
		{
			name:    "regexp not match function",
			pattern: `{{regexp.not_match("^foo$")}}`,
			matches: []string{"", "bar", "xfoo"},
			misses:  []string{"foo"},
		},
		{
			name:    "prefix and suffix",
			pattern: `foo-{{regexp.match("^bar$")}}-baz`,
			matches: []string{"foo-bar-baz"},
			misses:  []string{"bar", "foo-baz-baz", "xfoo-bar-baz", "foo-bar-bazx"},
		},
		{
			name:    "prefix and suffix with negation",
			pattern: `foo-{{regexp.not_match("^bar$")}}-baz`,
			matches: []string{"foo-other-baz"},
			misses:  []string{"foo-bar-baz", "other", "xfoo-other-baz"},
		},
		{
			name:    "prefix and suffix cannot overlap",
			pattern: `a{{regexp.not_match("x")}}a`,
			matches: []string{"aa", "aba"},
			misses:  []string{"a", "axa"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			matcher, err := Match(tt.pattern)
			if !assert.NoError(t, err) {
				return
			}
			for _, input := range tt.matches {
				assert.True(t, matcher.Match(input), "%q should match %q", input, tt.pattern)
			}
			for _, input := range tt.misses {
				assert.False(t, matcher.Match(input), "%q should not match %q", input, tt.pattern)
			}
		})
	}
}

// TestMatchErrors checks invalid matcher syntax and the documented diagnostics.
func TestMatchErrors(t *testing.T) {
	_, regexpErr := regexp.Compile("[")
	tests := []struct {
		name      string
		pattern   string
		wantError string
		contains  string
	}{
		{
			name:      "missing closing brackets",
			pattern:   `foo-{{regexp.match("bar")}`,
			wantError: `"foo-{{regexp.match(\"bar\")}" is using template brackets '{{' or '}}', however expression does not parse, make sure the format is {{expression}}`,
		},
		{
			name:      "missing opening brackets",
			pattern:   `foo-regexp.match("bar")}}`,
			wantError: `"foo-regexp.match(\"bar\")}}" is using template brackets '{{' or '}}', however expression does not parse, make sure the format is {{expression}}`,
		},
		{
			name:      "unsupported namespace",
			pattern:   `{{other.match("foo")}}`,
			wantError: "unsupported function namespace other, supported namespaces are email and regexp",
		},
		{
			name:      "unsupported regexp function",
			pattern:   `{{regexp.replace("foo")}}`,
			wantError: "unsupported function regexp.replace, supported functions are: regexp.match, regexp.not_match.",
		},
		{
			name:      "unsupported email function",
			pattern:   `{{email.domain("foo")}}`,
			wantError: "unsupported function email.domain, supported functions are: email.local",
		},
		{
			name:      "invalid regexp match",
			pattern:   `{{regexp.match("[")}}`,
			wantError: fmt.Sprintf("failed parsing regexp %q: %v", "[", regexpErr),
		},
		{
			name:      "invalid regexp not match",
			pattern:   `{{regexp.not_match("[")}}`,
			wantError: fmt.Sprintf("failed parsing regexp %q: %v", "[", regexpErr),
		},
		{
			name:     "no arguments",
			pattern:  `{{regexp.match()}}`,
			contains: "argument",
		},
		{
			name:     "two arguments",
			pattern:  `{{regexp.match("foo", "bar")}}`,
			contains: "argument",
		},
		{
			name:     "non-string argument",
			pattern:  `{{regexp.match(42)}}`,
			contains: "string literal",
		},
		{
			name:     "variable argument",
			pattern:  `{{regexp.match(internal.foo)}}`,
			contains: "string literal",
		},
		{
			name:     "nested function argument",
			pattern:  `{{regexp.match(regexp.match("foo"))}}`,
			contains: "string literal",
		},
		{
			name:     "variable expression",
			pattern:  `{{internal.foo}}`,
			contains: "is not a valid matcher expression - no variables and transformations are allowed",
		},
		{
			name:     "transformation",
			pattern:  `{{email.local(internal.foo)}}`,
			contains: "is not a valid matcher expression - no variables and transformations are allowed",
		},
		{
			name:     "multiple expressions",
			pattern:  `{{regexp.match("foo")}}{{regexp.match("bar")}}`,
			contains: "is not a valid matcher expression - no variables and transformations are allowed",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			matcher, err := Match(tt.pattern)
			assert.Nil(t, matcher)
			if !assert.IsType(t, trace.BadParameter(""), err) {
				return
			}
			if tt.wantError != "" {
				assert.EqualError(t, err, tt.wantError)
			}
			if tt.contains != "" {
				assert.True(t, strings.Contains(err.Error(), tt.contains), "%q should contain %q", err, tt.contains)
			}
		})
	}
