func containsMatcherFunction(expr ast.Expr) bool {
	found := false
	ast.Inspect(expr, func(node ast.Node) bool {
		call, ok := node.(*ast.CallExpr)
		if !ok {
			return true
		}
		selector, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		namespace, ok := selector.X.(*ast.Ident)
		if ok && namespace.Name == RegexpNamespace &&
			(selector.Sel.Name == RegexpMatchFnName || selector.Sel.Name == RegexpNotMatchFnName) {
			found = true
			return false
		}
		return true
	})
	return found
}

const (
	// LiteralNamespace is a namespace for Expressions that always return
	// static literal values.
	LiteralNamespace = "literal"
	// EmailNamespace is a function namespace for email functions
	EmailNamespace = "email"
	// EmailLocalFnName is a name for email.local function
	EmailLocalFnName = "local"
	// RegexpNamespace is a function namespace for regexp matchers.
	RegexpNamespace = "regexp"
	// RegexpMatchFnName is the positive regexp matcher function.
	RegexpMatchFnName = "match"
	// RegexpNotMatchFnName is the negative regexp matcher function.
	RegexpNotMatchFnName = "not_match"
)

// transformer is an optional value transformer function that can take in
// string and replace it with another value
type transformer interface {
	transform(in string) (string, error)
}

type walkResult struct {
	parts     []string
	transform transformer
	matcher   Matcher
}

// walk will walk the ast tree and gather all the variable parts into a slice and return it.
func walk(node ast.Node) (*walkResult, error) {
	var result walkResult

	switch n := node.(type) {
	case *ast.CallExpr:
		switch call := n.Fun.(type) {
		case *ast.Ident:
			return nil, trace.BadParameter("function %v is not supported", call.Name)
		case *ast.SelectorExpr:
			// Selector expression looks like email.local(parameter)
			namespace, ok := call.X.(*ast.Ident)
			if !ok {
				return nil, trace.BadParameter("expected namespace, e.g. email.local, got %v", call.X)
			}
			switch namespace.Name {
			case EmailNamespace:
				if call.Sel.Name != EmailLocalFnName {
					return nil, trace.BadParameter("unsupported function email.%s, supported functions are: email.local", call.Sel.Name)
				}
				if len(n.Args) != 1 {
					return nil, trace.BadParameter("expected 1 argument for email.local got %v", len(n.Args))
				}
				result.transform = emailLocalTransformer{}
				ret, err := walk(n.Args[0])
				if err != nil {
					return nil, trace.Wrap(err)
				}
				result.parts = ret.parts
				result.matcher = ret.matcher
				return &result, nil
			case RegexpNamespace:
				if call.Sel.Name != RegexpMatchFnName && call.Sel.Name != RegexpNotMatchFnName {
					return nil, trace.BadParameter("unsupported function regexp.%s, supported functions are: regexp.match, regexp.not_match.", call.Sel.Name)
				}
				if len(n.Args) != 1 {
					return nil, trace.BadParameter("expected 1 argument for regexp.%s got %v", call.Sel.Name, len(n.Args))
				}
				argument, ok := n.Args[0].(*ast.BasicLit)
				if !ok || argument.Kind != token.STRING {
					return nil, trace.BadParameter("expected a string literal argument for regexp.%s", call.Sel.Name)
				}
				pattern, err := strconv.Unquote(argument.Value)
				if err != nil {
					return nil, trace.BadParameter("invalid string literal %q: %v", argument.Value, err)
				}
				re, err := regexp.Compile(pattern)
				if err != nil {
					return nil, trace.BadParameter("failed parsing regexp %q: %v", pattern, err)
				}
				result.matcher = regexpMatcher{re: re}
				if call.Sel.Name == RegexpNotMatchFnName {
					result.matcher = notMatcher{matcher: result.matcher}
				}
				return &result, nil
			default:
				return nil, trace.BadParameter("unsupported function namespace %s, supported namespaces are email and regexp", namespace.Name)
			}
		default:
			return nil, trace.BadParameter("unsupported function %T", n.Fun)
		}
	case *ast.IndexExpr:
		ret, err := walk(n.X)
		if err != nil {
			return nil, err
		}
		result.parts = append(result.parts, ret.parts...)
		ret, err = walk(n.Index)
		if err != nil {
			return nil, err
		}
		result.parts = append(result.parts, ret.parts...)
		return &result, nil
	case *ast.SelectorExpr:
		ret, err := walk(n.X)
		if err != nil {
			return nil, err
		}
		result.parts = append(result.parts, ret.parts...)

		ret, err = walk(n.Sel)
		if err != nil {
			return nil, err
		}
		result.parts = append(result.parts, ret.parts...)
		return &result, nil
	case *ast.Ident:
		return &walkResult{parts: []string{n.Name}}, nil
	case *ast.BasicLit:
		if n.Kind == token.STRING {
			var err error
			n.Value, err = strconv.Unquote(n.Value)
			if err != nil {
				return nil, err
			}
		}
		return &walkResult{parts: []string{n.Value}}, nil
	default:
		return nil, trace.BadParameter("unknown node type: %T", n)
	}
}

